```latex
\section{Preliminaries}
\label{section:preliminaries}

\subsection{Basic graph terminology}
In this work, all graphs considered are undirected multigraphs (i.e., they may have parallel edges). Let $G=(V,E)$ be a graph. 

\subsection{Notation}
We use $\bot$ to denote the end-of-list element. 

\section{Concepts defined on DFS-tree}
\label{section:DFS}

Throughout this chapter we assume that $G$ is a connected graph with $n$ vertices and $m$ edges, and $r$ is a vertex of $G$. 

\subsection{Basic definitions}
\label{subsection:basic-dfs}
Let $T$ be a DFS-tree of $G$ with start vertex $r$ \cite{DBLP:journals/siamcomp/Tarjan72}. We identify the vertices of $G$ with their order of visit by the DFS. (Thus, $r=1$, and the last vertex visited by $G$ is $n$.) We let $T[v,u]$ denote the simple path from $v$ to $u$ on $T$, for any two vertices $v$ and $u$ of $G$. If $v$ lies on the tree-path $T[r,u]$, then we say that $v$ is an ancestor of $u$ (equivalently, $u$ is a descendant of $v$). Notice that if $v$ is an ancestor of $u$, then $v\leq u$. If $v$ is an ancestor of $u$ such that $v\neq u$, then we say that $v$ is a proper ancestor of $u$ (equivalently, $u$ is a proper descendant of $v$).

Every non-tree of $G$ has its endpoints related as ancestor and descendant on $T$ \cite{DBLP:journals/siamcomp/Tarjan72}. Thus, the non-tree edges of $G$ are called ``back-edges". Whenever we let $(x,y)$ denote a back-edge, we always assume that $x$ is the higher endpoint of $(x,y)$ (i.e., $x>y$). Thus, $x$ is the endpoint of $(x,y)$ that is a descendant of $y$. For a vertex $v\neq r$, we say that a back-edge $(x,y)$ leaps over $v$ if $x$ is a descendant of $v$ and $y$ is a proper ancestor of $v$. We let $B(v)$ denote the set of the back-edges that leap over $v$. 

\subsubsection{$\mathit{low}$ and $\mathit{high}$ edges}
First, let $(v,z_1),\dots,(v,z_s)$ be the list of the back-edges with higher endpoint $v$, sorted in increasing order w.r.t. their lower endpoint. (Notice that these back-edges belong to $B(v)$.) Then we let $l_i(v)$ denote $z_i$, for every $i\in\{1,\dots,s\}$. If $i>s$, then we let $l_i(v)=v$. The vertex $l_1(v)$ is of particular importance, and we may denote it simply as $l(v)$.

\subsection{Computing the leftmost and the rightmost edges}
\label{subsection:leftmost}

Let $v\neq r$ be a vertex, and let $(x_1,y_1),\dots,(x_k,y_k)$ be the list of the back-edges in $B(v)$ sorted in lexicographic order. In other words, we have $x_1\leq\dots\leq x_k$, and if $x_i=x_{i+1}$ then $y_i\leq y_{i+1}$, for any $i\in\{1,\dots,k-1\}$.

For every $t=1,2,\dots$, we let $L(v,c,t)$ denote the set of the first $t$ back-edges in $B(v)$ whose higher endpoint is a descendant of $c$. More precisely, $L(v,c,t)$ is defined as follows. Let $i$ be the lowest index in $\{1,\dots,k\}$ such that $x_i$ is a descendant of $c$. If such an index does not exist, then we let $L(v,c,t)=\emptyset$. Otherwise, let $j$ be the maximum index in $\{i,\dots,i+t-1\}$ such that $x_j$ is a descendant of $c$. Then $L(v,c,t)=\{(x_i,y_i),\dots,(x_j,y_j)\}$.

Thus, for every vertex $x$, we maintain a boolean attribute $\mathit{is\_active}(x)$, which is \emph{true} if and only if $x$ is active. We use a disjoint-set union data structure $\mathit{DSU}$ on the set of inactive vertices, that maintains the partition of the maximal segments (w.r.t. the DFS numbering) of inactive vertices. Thus, if two vertices $x$ and $x+1$ are inactive, then they belong to the same set maintained by the DSU data structure. $\mathit{DSU}$ supports the operations $\mathtt{find}(x)$ and $\mathtt{unite}(x,y)$. We use $\mathtt{find}(x)$, on an inactive vertex $x$, in order to return a representative of the segment of inactive vertices that contains $x$. With the operation $\mathtt{unite}(x,y)$ we unite the segment that contains $x$ with the segment that contains $y$ (we assume that $y=x+1$). Also, for every vertex $x$, we maintain two pointers $\mathit{left}(x)$ and $\mathit{right}(x)$. These are only used when $x$ is an inactive vertex, which is a representative of its segment $S$. In this case, $\mathit{left}(x)$ points to the greatest vertex that is lower than $x$ and not in $S$, and $\mathit{right}(x)$ points to the lowest vertex that is greater than $x$ and not in $S$. Then, by definition, we have that $\mathit{left}(x)$ (resp., $\mathit{right}(x)$) is either an active vertex, or $\bot$. We maintain the invariant that, whenever a DSU operation changes the representative of a segment, it passes the $\mathit{left}$ and the $\mathit{right}$ pointer of the old representative to the new one (so that we can correctly retrieve the endpoints of the corresponding maximal segment).

\begin{algorithm}[H]
\caption{\textsf{Compute the sets $L(v_1,c_1,t_1),\dots,L(v_N,c_N,t_N)$, where $c_i$ is a descendant of $v_i$, for every $i\in\{1,\dots,N\}$}}
\label{algorithm:L-sets}
\LinesNumbered
\DontPrintSemicolon
let $Q$ be the list of all triples $(v_1,c_1,t_1),\dots,(v_N,c_N,t_N)$ sorted in decreasing order w.r.t. the first component\;
\label{line:L-sort-1}
sort the adjacency list of every vertex in increasing order w.r.t. the lower endpoints\;
\label{line:L-sort-2}
initialize a boolean array $\mathit{is\_active}$ with $n$ entries\;
\lForEach{vertex $v$}{set $\mathit{is\_active}[v]\leftarrow\mathit{true}$}
\lForEach{vertex $v$}{initialize two pointers $v.\mathit{left}\leftarrow v-1$ and $v.\mathit{right}\leftarrow v+1$}
\label{line:L-pointers}
\ForEach{$(v,c,t)\in Q$}{
\label{line:L-for-query}
  let $L(v,c,t)\leftarrow\emptyset$\;
  set $\mathit{counter}\leftarrow 0$ \tcp{counter for the number of back-edges we have collected}
  \label{line:L-count-0}
  let $x\leftarrow c$\;
  \label{line:set-x-c}
  \If{$\mathit{is\_active}(x)=\mathit{false}$}{
  \label{line:L-if-c-active}
    $x\leftarrow\mathtt{find}(x).\mathit{right}$\;
    \label{line:L-x-next-c}
  }
  \While{$x\neq\bot$ \textbf{and} $x$ is a descendant of $c$}{
  \label{line:L-while}
    \If{$l(x)<v$}{
    \label{line:L-x-provides}
      let $e=(x,y)$ be the first back-edge in the adjacency list of $x$\;
      \label{line:L-x-provides-1}
      \While{$y<v$ \textbf{and} $\mathit{counter}<t$}{
      \label{line:L-x-while-2}  
        insert $(x,y)$ into $L(v,c,t)$\;
        $\mathit{counter}\leftarrow\mathit{counter}+1$\;
        let $e=(x,y)$ be the next back-edge in the adjacency list of $x$\;
        \lIf{$e=\bot$}{\textbf{break}}
      }
      \lIf{$\mathit{counter}=t$}{\textbf{break}}
      \label{line:L-x-provides-2}
    }
    \Else{
      $\mathit{is\_active}(x)\leftarrow\mathit{false}$\;
      \label{line:L-x-deactivate}
      \If{$\mathit{is\_active}(x-1)=\mathit{false}$ \textbf{and} $\mathit{is\_active}(x+1)=\mathit{true}$}{
      \label{line:L-x-deactivate-1}
        $\mathtt{unite}(x-1,x)$\;
        \label{line:L-x-unite-1}
        $\mathtt{find}(x).\mathit{right}\leftarrow x+1$\;  
        \label{line:L-x-set-right}
      }
      \If{$\mathit{is\_active}(x-1)=\mathit{true}$ \textbf{and} $\mathit{is\_active}(x+1)=\mathit{false}$}{
        $\mathtt{unite}(x,x+1)$\;
        $\mathtt{find}(x).\mathit{left}\leftarrow x-1$\; 
      }    
      \If{$\mathit{is\_active}(x-1)=\mathit{false}$ \textbf{and} $\mathit{is\_active}(x+1)=\mathit{false}$}{
        $\mathtt{unite}(x-1,x)$\;
        \label{line:L-x-unite-x-1}
        $\mathtt{unite}(x,x+1)$\;
        \label{line:L-x-unite-x+1}
      }          
      \label{line:L-x-deactivate-2}
    }
    $x\leftarrow x+1$\;
    \label{line:L-x-next-1}
    \lIf{$x=\bot$}{\textbf{break}}
    \If{$\mathit{is\_active}(x)=\mathit{false}$}{
       $x\leftarrow\mathtt{find}(x).\mathit{right}$\;
       \label{line:L-x-next-3}
    }
    \label{line:L-x-next-2}
  }
}
\end{algorithm}
```


