\begin{proposition}
\label{proposition:L-sets}
Let $L(v_1,c_1,t_1),\dots,L(v_N,c_N,t_N)$ be a collection of queries, where $c_i$ is a descendant of $v_i$, for every $i\in\{1,\dots,N\}$, and $t_i\geq 1$. Then Algorithm~\ref{algorithm:L-sets} correctly computes the sets $L(v_1,c_1,t_1),\dots,L(v_N,c_N,t_N)$. Furthermore, it runs in $O(t_1+\dots+t_N+m)$ time.
\end{proposition}
